+                 (long long) coverage.last_begin, (long long) coverage.last_count,
+                 stats.ms_total);
+    std::fprintf(stderr, "full-main-context-probe: experts streamed=%lld dma=%lld resident=%lld cpu=%lld host_ms=%.1f ple_ms=%.1f\n",
